const rows = $input.all();
const now = new Date();
const windowMs = 60 * 60 * 1000;

const recentTickets = rows.filter(row => {
  const ts = new Date(row.json.timestamp);
  return (now - ts) < windowMs;
});

const grouped = {};
recentTickets.forEach(row => {
  const cat = row.json.category?.toLowerCase();
  if (!cat) return;
  if (!grouped[cat]) grouped[cat] = [];
  grouped[cat].push(row.json.ticket_id);
});

const spikes = Object.entries(grouped)
  .filter(([cat, ids]) => ids.length >= 3);

// Find category with highest ticket count
const topCategory = Object.entries(grouped)
  .sort((a, b) => b[1].length - a[1].length)[0];

const topCategoryName = topCategory ? topCategory[0] : '';
const topCategoryCount = topCategory ? topCategory[1].length : 0;
const topCategoryTickets = topCategory ? topCategory[1].join(', ') : '';

return [{
  json: {
    shouldAlert: spikes.length > 0,
    count: recentTickets.length,
    topCategory: topCategoryName,
    topCategoryCount: topCategoryCount,
    topCategoryTickets: topCategoryTickets
  }
}];
